pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 maxDeposits) public {
        // bound to a reasonable range to avoid excessive gas, but wide enough to trigger overflow
        maxDeposits = bound(maxDeposits, 1, 300);
        // Use a fixed EOA approach: we will call receive() many times with 0 value.
        // The reference contract will revert once depositsCount overflows uint256.
        // The buggy contract never reverts and continues incrementing.
        address actor = address(0x1234);
        vm.deal(actor, 0);
        uint256 successes = 0;
        for (uint256 i = 0; i < maxDeposits; i++) {
            vm.prank(actor);
            try c.receive{value: 0}() {
                successes++;
            } catch {}
        }
        // General rule: depositsCount must never exceed the number of successful receive calls.
        // The reference enforces this via overflow check; the buggy one allows depositsCount to exceed successes.
        assertTrue(c.depositsCount() <= successes);
    }
}

