pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint8 count) public {
        vm.assume(count > 0);
        vm.assume(amount >= 1);
        uint256 totalCalls = uint256(count);
        // Ensure total sent is affordable for the fuzzed actor
        uint256 totalSent = amount * totalCalls;
        vm.assume(totalSent / totalCalls == amount); // no overflow
        address sender = address(0x1234);
        vm.deal(sender, totalSent);
        vm.startPrank(sender);
        for (uint256 i = 0; i < totalCalls; i++) {
            (bool ok, ) = address(c).call{value: amount}("");
        }
        vm.stopPrank();
        // In reference, depositsCount equals min(totalCalls, type(uint).max - initial) which is at most totalCalls.
        // In buggy, it increments every time even beyond total possible non-overflowing calls, so > totalCalls is possible.
        assertTrue(c.depositsCount() <= totalCalls);
    }
}

