pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint8 count) public {
        // Bound to prevent test from running forever, but wide enough to include the overflow
        uint8 n = uint8(bound(count, 1, 255));

        // Advance depositsCount close to max by warping to a high block number and making calls
        // We need to set up a state where further deposits will overflow depositsCount but balance won't overflow uint256
        // Since depositsCount is uint, we can set it to type(uint).max - n + 1 using a helper that deposits n-1 times, then test with one more.

        // Use a fresh helper contract that can repeatedly deposit without hitting gas limits via loop
        Helper helper = new Helper();
        // First, we need to get depositsCount to a high value. We can't directly set it, so we'll make many deposits.
        // But for the invariant to hold, we need a way to check proportionality without hardcoding amounts.
        // Alternative: Invariant: depositsCount == number of receive() calls made (if we count them).

        // Simpler rule: For any sequence of receive calls with non-zero value, the depositsCount must equal the total number of successful receive calls.
        // The bug breaks this when overflow occurs, because depositsCount wraps but the actual number of calls continues to increase.
        // We can count the calls ourselves in the test and compare.

        uint256 callCount = 0;
        // Make n calls
        vm.startPrank(address(helper));
        for (uint256 i = 0; i < n; i++) {
            // We use helper's receive to forward 1 wei to C's receive
            vm.deal(address(helper), 1 wei);
            helper.depositTo{value: 1}(address(c));
            callCount++;
        }
        vm.stopPrank();

        // Now check that depositsCount equals callCount
        assertTrue(c.depositsCount() == callCount);
    }
}

contract Helper {
    function depositTo(address target) external payable {
        (bool ok, ) = target.call{value: msg.value}("");
        require(ok);
    }
}

