pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // bound the amount to a reasonable range that allows transfer
        vm.assume(amount > 0 && amount <= 1e18);
        // fund the owner so they can trigger receive
        vm.deal(address(c), 0);
        // we need an external actor to send Ether to c via receive
        vm.deal(address(this), amount * 2);

        // record initial state
        uint256 initialDeposits = c.depositsCount();
        uint256 initialBalance = address(c).balance;

        // send Ether to c via receive
        (bool success, ) = address(c).call{value: amount}("");
        require(success, "first receive failed");

        // now withdrawAll – but the owner must call it, and we are the owner (deployer)
        c.withdrawAll();

        // invariant: depositsCount + (# of successful withdrawAll calls that fully drain) == initialDeposits + (# of receive calls)
        // Here we had 1 receive call, then 1 withdrawAll that should fully drain the contract.
        // Thus: depositsCount + 1 == initialDeposits + 1.
        // Since initialDeposits == 0 for the first call, we assert depositsCount == 1.
        assertTrue(c.depositsCount() == 1);
    }
}

