pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    uint256 constant INITIAL_BALANCE = 100 ether;

    function setUp() public {
        c = new C();
        // Fund the contract with some Ether to withdraw
        vm.deal(address(c), INITIAL_BALANCE);
        // Receive Ether so depositsCount is consistent
        vm.prank(address(c));
        (bool ok,) = address(c).call{value: 0}("");
        require(ok, "setUp receive failed");
    }

    function testFuzz_property(uint256 _value) public {
        // Bound _value to a reasonable range that is within the contract's balance
        _value = bound(_value, 1, INITIAL_BALANCE);

        // Deploy a failing callee (adversarial counterpary)
        Reverter reverter = new Reverter();
        vm.deal(address(reverter), 0);

        // Record balance before
        uint256 balanceBefore = address(c).balance;

        // Owner sends some value via sendMoney to the failing callee, then withdrawAll
        // We need to first send money so that withdrawAll's external call encounters the
        // failing callee (through the call inside sendMoney).  Actually, withdrawAll calls
        // withdraw which does a transfer to owner.  To make the difference appear via
        // an external party's behavior, we need withdrawAll to invoke an external call
        // that can fail.  The contract has sendMoney which uses low-level call.  So:
        // 1. Owner uses sendMoney to send _value to the failing reverter.
        // 2. Then owner calls withdrawAll.
        // The rule: after these operations, the contract's balance is less than before
        // (because sendMoney transfers out _value even though the call reverts? No, low-level
        // call forwards Ether regardless of success, so _value leaves the contract even if
        // the callee reverts.  The correct contract then also transfers remaining balance to
        // owner via withdrawAll.  The buggy contract reverts on withdrawAll, keeping the
        // remaining balance minus _value.

        vm.prank(c.owner());
        (bool sent,) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", address(reverter), _value));
        require(sent, "sendMoney failed");

        vm.prank(c.owner());
        (bool wd,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        // wd may be true or false; we don't assert on it directly.

        uint256 balanceAfter = address(c).balance;

        // The reference always reduces balance by at least _value (sendMoney transfers _value,
        // then withdrawAll transfers the rest). If _value == INITIAL_BALANCE, sendMoney
        // transfers everything and withdrawAll transfers nothing.  In all cases, balanceAfter
        // is strictly less than balanceBefore because _value >= 1.
        // The buggy contract reverts on withdrawAll, so balance remains balanceBefore - _value
        // which is still less than balanceBefore. Both satisfy the strict inequality.
        // That's not the right property.

        // Let's instead craft a property about the owner's balance increase.
        // That requires recording owner's balance before and after, but the owner is
        // address(this) in setUp? No, owner is msg.sender of constructor, which is this test
        // contract. We can prank as owner. So owner is address(this).  We can measure
        // owner's balance change.

        // We'll redo the logic inside the fuzz test with correct balance tracking.
        vm.prank(c.owner());
        (bool sent2,) = address(c).call{value: 0}(abi.encodeWithSignature("sendMoney(address,uint256)", address(reverter), _value));
        require(sent2, "sendMoney2 failed");

        uint256 ownerBalanceBefore = address(c.owner()).balance;
        vm.prank(c.owner());
        (bool wd2,) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        uint256 ownerBalanceAfter = address(c.owner()).balance;

        // In the reference, after sendMoney (which reduces contract's balance by _value),
        // withdrawAll transfers the rest to owner. So owner's balance increases by
        // (INITIAL_BALANCE - _value).  In the buggy version, withdrawAll reverts, so
        // owner's balance does not increase.  So the property: owner's balance strictly increases.

        assertTrue(ownerBalanceAfter > ownerBalanceBefore, "Owner balance should increase");
    }
}

